INSERT INTO public.economy_config(key,value,description) VALUES
('fob_size_multipliers','[0.70,0.85,1.00,1.25,1.60,2.00,2.50]'::jsonb,'FBO base setup and weekly base upkeep multiplier by airport size 1-7 (Size 3 = 1.00 baseline)')
ON CONFLICT (key) DO NOTHING;

CREATE OR REPLACE FUNCTION public.fob_size_multiplier(p_icao text) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT coalesce((SELECT (e.value->>(greatest(1,least(7,coalesce(a.size,3)))-1))::numeric FROM public.airports a, public.economy_config e WHERE a.icao=upper(p_icao) AND e.key='fob_size_multipliers'),1.0)
$$;
REVOKE ALL ON FUNCTION public.fob_size_multiplier(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fob_size_multiplier(text) TO authenticated;

CREATE OR REPLACE FUNCTION public.fob_weekly_cost(p_base uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT round(economy_number(CASE WHEN b.base_type='MAIN' THEN 'fob_main_upkeep' ELSE 'fob_satellite_upkeep' END)*public.fob_size_multiplier(b.airport_icao),2)+CASE WHEN has_fuel_contract THEN economy_number('fob_fuel_upkeep') ELSE 0 END+CASE WHEN has_handling_desk THEN economy_number('fob_handling_upkeep') ELSE 0 END+CASE WHEN has_maintenance_bay THEN economy_number('fob_maintenance_upkeep') ELSE 0 END FROM company_fobs b JOIN companies c ON c.id=b.company_id WHERE b.id=p_base AND c.user_id=auth.uid() $$;

CREATE OR REPLACE FUNCTION public.manage_fob(p_action text, p_airport text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_base uuid DEFAULT NULL::uuid, p_module text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE c companies%ROWTYPE; b company_fobs%ROWTYPE; cost numeric; bal numeric; bid uuid; kind text; label text; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM process_due_obligations(); PERFORM assert_company_investment(); bal:=company_balance(c.id); IF p_action='open' THEN IF p_type IS NULL OR p_type NOT IN ('MAIN','SATELLITE') THEN RAISE EXCEPTION 'Choose a base type'; END IF; IF p_type='MAIN' AND EXISTS(SELECT 1 FROM company_fobs WHERE company_id=c.id AND base_type='MAIN' AND closed_at IS NULL) THEN RAISE EXCEPTION 'Only one Main FOB is allowed'; END IF; IF p_type='SATELLITE' AND NOT EXISTS(SELECT 1 FROM company_fobs WHERE company_id=c.id AND base_type='MAIN' AND closed_at IS NULL) THEN RAISE EXCEPTION 'Open your Main FOB first'; END IF; IF p_type='SATELLITE' AND (SELECT count(*) FROM company_fobs WHERE company_id=c.id AND base_type='SATELLITE' AND closed_at IS NULL)>=2 THEN RAISE EXCEPTION 'Maximum two Satellite FOBs'; END IF; cost:=round(economy_number(CASE WHEN p_type='MAIN' THEN 'fob_main_setup' ELSE 'fob_satellite_setup' END)*public.fob_size_multiplier(upper(p_airport)),2); IF bal<cost THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; INSERT INTO company_fobs(company_id,airport_icao,base_type) VALUES(c.id,upper(p_airport),p_type) RETURNING * INTO b; kind:='FOB_SETUP'; label:='Open '||p_type||' FOB · '||b.airport_icao; ELSIF p_action='module' THEN SELECT * INTO b FROM company_fobs WHERE id=p_base AND company_id=c.id AND closed_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Base not found'; END IF; IF p_module='fuel' AND NOT b.has_fuel_contract THEN cost:=economy_number('fob_fuel_setup'); UPDATE company_fobs SET has_fuel_contract=true WHERE id=b.id; ELSIF p_module='handling' AND NOT b.has_handling_desk THEN cost:=economy_number('fob_handling_setup'); UPDATE company_fobs SET has_handling_desk=true WHERE id=b.id; ELSIF p_module='maintenance' AND NOT b.has_maintenance_bay THEN cost:=economy_number('fob_maintenance_setup'); UPDATE company_fobs SET has_maintenance_bay=true WHERE id=b.id; ELSE RAISE EXCEPTION 'Invalid or already installed module'; END IF; IF bal<cost THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; kind:='FOB_MODULE'; label:=p_module||' module · '||b.airport_icao; ELSE RAISE EXCEPTION 'Unknown base action'; END IF; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,kind,'FOB_ASSET','COMPANY_CASH',cost,-cost,bal-cost,label,b.id::text,'fob:'||b.id||':'||p_action||':'||coalesce(p_module,'setup')); RETURN b.id; END $function$;